import{v as d,_ as l,c as i,o as r,j as a,at as o,a as t}from"./chunks/framework.BlwsHpGA.js";d(()=>document==null?void 0:document.documentElement.classList.add("light","no-head"));const m=JSON.parse('{"title":"김민영 — 프론트엔드","description":"효율을 셜계하는 프론트엔드 개발자","frontmatter":{"layout":"doc","sidebar":false,"title":"김민영 — 프론트엔드","description":"효율을 셜계하는 프론트엔드 개발자","tags":["Frontend","Design system","Data Visualization","Vue","React","Nuxt"],"outline":false,"footer":false,"prev":false,"next":false},"headers":[],"relativePath":"resume_toss.md","filePath":"resume_toss.md"}'),s={name:"resume_toss.md"};function b(n,e,v,h,c,u){return r(),i("div",null,[...e[0]||(e[0]=[a("h1",{id:"김민영",tabindex:"-1"},[t("김민영 "),a("a",{class:"header-anchor",href:"#김민영","aria-label":'Permalink to "김민영"'},"​")],-1),a("div",{className:"kicker"},"Frontend Engineer(Developer)",-1),a("div",{class:"be-button text gray"},[a("i",{class:"icon left xi-mail-o"}),t(" noistommy@gmail.com ")],-1),a("div",{class:"be-button text gray"},[a("i",{class:"icon left xi-mobile"}),t(" 010-4456-9329 ")],-1),a("hr",null,null,-1),a("div",{className:"lead"},[a("p",null,"효율을 설계하는 프론트엔드 개발자 김민영입니다."),a("p",null,"프론트엔드 시스템 설계와 UI/UX 설계를 개발 효율성을 중요한 부분으로 생각하고 여러 서비스에서 디자인 시스템과 공용 라이브러리를 개발하고 생산성을 높인 경험이 있습니다. 직접 공용 모듈 및 유틸리티 기능 개발을 하여 서비스 전반의 재사용성과 확장성을 높여 유지보수 및 관리의 비용을 줄이는데 도움이 되도록 작업하고 있습니다."),a("p",null,"그동안 프론트엔드의 전반적인 업무를 폭넓게 수행해 왔고 특히 데이터 시각화 분야에서 SVG, canvas등 다양한 인터랙션을 적극 활용하고 있으며 최근에는 3D를 이용한 인터랙션에도 크게 관심을 갖고 개발하고 있습니다."),a("p",null,"최근 AI를 이용한 데이터 시각화 작업의 경험과 AI를 활용한 개발 등 AI 관련 기술을 활용하여 그동안의 쌓아온 역량과 결합하는 시도들을 계속해서 하고 있습니다."),a("p",null,"프레임워크 시스템 설계와 디자인 시스템의 도입으로 개발 생산성 향상을 경험했습니다. 팀과 서비스 전반에 재사용성과 확장성을 높이는 설계 기준을 마련하고 개발자 경험을 담아 직접 디자인 시스템과 공용 컴포넌트들을 개발하고 배포 하고 있습니다.")],-1),o('<h2 id="경력" tabindex="-1" data-v-bd5a78e6>경력 <a class="header-anchor" href="#경력" aria-label="Permalink to &quot;경력&quot;" data-v-bd5a78e6>​</a></h2><h3 id="주-포그리트-frontend-developer" tabindex="-1" data-v-bd5a78e6>(주) 포그리트 <span class="be-gray-text light" data-v-bd5a78e6>| Frontend Developer</span> <a class="header-anchor" href="#주-포그리트-frontend-developer" aria-label="Permalink to &quot;(주) 포그리트 &lt;span class=&quot;be-gray-text light&quot;&gt;| Frontend Developer&lt;/span&gt;&quot;" data-v-bd5a78e6>​</a></h3><p class="range-date" data-v-bd5a78e6>2023.12 – 2025.05 (1Y 6M)</p><blockquote data-v-bd5a78e6><p data-v-bd5a78e6><strong data-v-bd5a78e6>사용자 UX 데이터를 기반한 분석 데이터 시각화 구현 및 서비스 고도화를 담당</strong></p></blockquote><div class="py-10" data-v-bd5a78e6><h5 id="svg-기반-인터렉티브-컴포넌트-구현" tabindex="-1" data-v-bd5a78e6>SVG 기반 인터렉티브 컴포넌트 구현 <a class="header-anchor" href="#svg-기반-인터렉티브-컴포넌트-구현" aria-label="Permalink to &quot;SVG 기반 인터렉티브 컴포넌트 구현&quot;" data-v-bd5a78e6>​</a></h5><ul data-v-bd5a78e6><li data-v-bd5a78e6><strong data-v-bd5a78e6>문제</strong>: 기존의 방식(Lottie, SVGator)으로는 복잡한 인터랙션과 사실적인 움직임 구현이 불가능함.</li><li data-v-bd5a78e6><strong data-v-bd5a78e6>해결</strong>: SVG를 코드 레벨에서 직접 구현하여 상호작용에 따른 동적 애니메이션 처리와 가속도 조정과 requestAnimationFrame을 통한 사실적인 움직임을 구현함.</li><li data-v-bd5a78e6><strong data-v-bd5a78e6>결과</strong>: 서비스의 메인 컨텐츠로서 프로젝트 완료에 기여하고 팀내 긍정적 평가를 받음.</li></ul><h5 id="시스템-폰트의-문제-개선-및-최적화" tabindex="-1" data-v-bd5a78e6>시스템 폰트의 문제 개선 및 최적화 <a class="header-anchor" href="#시스템-폰트의-문제-개선-및-최적화" aria-label="Permalink to &quot;시스템 폰트의 문제 개선 및 최적화&quot;" data-v-bd5a78e6>​</a></h5><ul data-v-bd5a78e6><li data-v-bd5a78e6><strong data-v-bd5a78e6>문제</strong>: 사용중인 시스템 폰트 사용과 국제화 지원으로 인해 화면 깜박임(FOIT, FOUT) 문제 발생.</li><li data-v-bd5a78e6><strong data-v-bd5a78e6>해결</strong>: 서브셋 폰트와 국제화 지원이 가능한 &#39;Pretendard Variable&#39;폰트를 &#39;preload&#39; 방식으로 최적화하여 FOIT, FOUT를 최대한 줄이고 추가적으로 일관된 폰트 사용으로 인한 스타일 일관성을 확보할 수 있게됨.</li><li data-v-bd5a78e6><strong data-v-bd5a78e6>결과</strong>: 전사 서비스에 적용되어 서비스 신뢰도를 높이고 국제화 폰트별 스타일을 통일해 디자인 비용 소모를 줄임.</li></ul><h5 id="재사용-공용-모듈-개발" tabindex="-1" data-v-bd5a78e6>재사용 공용 모듈 개발 <a class="header-anchor" href="#재사용-공용-모듈-개발" aria-label="Permalink to &quot;재사용 공용 모듈 개발&quot;" data-v-bd5a78e6>​</a></h5><ul data-v-bd5a78e6><li data-v-bd5a78e6><strong data-v-bd5a78e6>문제</strong>: 서비스에 공통적으로 사용되는 Tooltip, Modal 기능이 각 서비스에서 개별적으로 사용되면서 코드 일관성, 유지보수의 어려움이 발생함.</li><li data-v-bd5a78e6><strong data-v-bd5a78e6>해결</strong>: 컴포넌트를 재사용이 가능한 외부 모듈로 만들어서 관리하고 각 서비스로 임포트 하도록 설계하여 유지보수 비용을 줄이고 일관된 스타일 및 기능을 제공하도록 함.</li><li data-v-bd5a78e6><strong data-v-bd5a78e6>결과</strong>: 재사용 모듈 사용으로 기존 프로젝트의 유지보수와 신규 프로젝트의 기능 추가 비용을 줄이는 효과. (기존 프로젝트 2개, 신규 프로젝트 2개)</li></ul><div class="be-button compact small mb-5" data-v-bd5a78e6> Modal 모듈 문서 <i class="icon right xi-link" data-v-bd5a78e6></i><a class="link" href="https://noistommy.github.io/vue-nt-modal" target="_blank" data-v-bd5a78e6></a></div><br data-v-bd5a78e6><div class="be-button compact small" data-v-bd5a78e6> Tooltip 모듈 문서 <i class="icon right xi-link" data-v-bd5a78e6></i><a class="link" href="https://noistommy.github.io/vue-nt-tooltip" target="_blank" data-v-bd5a78e6></a></div></div><h3 id="주-가비아-frontend-developer" tabindex="-1" data-v-bd5a78e6>(주) 가비아 <span class="be-gray-text light" data-v-bd5a78e6>| Frontend Developer</span> <a class="header-anchor" href="#주-가비아-frontend-developer" aria-label="Permalink to &quot;(주) 가비아 &lt;span class=&quot;be-gray-text light&quot;&gt;| Frontend Developer&lt;/span&gt;&quot;" data-v-bd5a78e6>​</a></h3><p class="range-date" data-v-bd5a78e6>2019.11 – 2023.02 (3Y 4M)</p><blockquote data-v-bd5a78e6><p data-v-bd5a78e6><strong data-v-bd5a78e6>신규 서비스 프레임워크 시스템 설계 및 개발과 공용 컴포넌트 라이브러리 개발 담당</strong></p></blockquote><div class="py-10" data-v-bd5a78e6><h5 id="하이웍스-그룹웨어-신규-서비스-개발" tabindex="-1" data-v-bd5a78e6>하이웍스 그룹웨어 신규 서비스 개발 <a class="header-anchor" href="#하이웍스-그룹웨어-신규-서비스-개발" aria-label="Permalink to &quot;하이웍스 그룹웨어 신규 서비스 개발&quot;" data-v-bd5a78e6>​</a></h5><ul data-v-bd5a78e6><li data-v-bd5a78e6><strong data-v-bd5a78e6>문제</strong>: 프레임워크(vue)로 전환 초기 기술 부재로 상태관리 방식, SPA 구조 설계, 폴더 구성들에 문제가 많아 일정이 지연됨.</li><li data-v-bd5a78e6><strong data-v-bd5a78e6>해결</strong>: TF팀에 참여 하여 기존 설계 및 코드의 50%를 재 구현하며 문제를 개선하여 개발을 완료.</li><li data-v-bd5a78e6><strong data-v-bd5a78e6>결과</strong>: 1년간 지연된 프로젝트를 마무리 할 수 있었고 전사 프레임워크 기술 정책에 기준을 마련하고 이후 2개의 서비스 개발에 활용함.</li></ul><h5 id="디자인-시스템-기반-ui-컴포넌트-개발" tabindex="-1" data-v-bd5a78e6>디자인 시스템 기반 UI 컴포넌트 개발 <a class="header-anchor" href="#디자인-시스템-기반-ui-컴포넌트-개발" aria-label="Permalink to &quot;디자인 시스템 기반 UI 컴포넌트 개발&quot;" data-v-bd5a78e6>​</a></h5><ul data-v-bd5a78e6><li data-v-bd5a78e6><strong data-v-bd5a78e6>문제</strong>: 서비스 마다 생성된 UI 컴포넌드와 외부 컴포넌트 라이브러리로 인해 일관되지 않은 스타일과 중복 컴포넌트등의 문제가 발생함.</li><li data-v-bd5a78e6><strong data-v-bd5a78e6>해결</strong>: <ol data-v-bd5a78e6><li data-v-bd5a78e6>자체 컴포넌트를 구현하여 외부 컴포넌트를 대체하고 중복된 컴포넌트들을 하나로 통합하여 자체 라이브러리를 생성. (36개 컴포넌트)</li><li data-v-bd5a78e6>디자인 토큰을 정의하여 디자인 시스템을 만들고 컴포넌트의 스타일을 분리해서 빌드를 통해 정적파일(.css)로 컴파일함</li><li data-v-bd5a78e6>디자인, 기획 팀과의 소통을 위한 문서 사이트를 개발 및 운영.</li></ol></li><li data-v-bd5a78e6><strong data-v-bd5a78e6>결과</strong>: 자체 라이브러리를 적용하여 초기 설계 기간 50% 단축. 유료 라이브러리(CKEDITOR)를 대체 하여 생산 비용 감소.</li></ul><div class="be-button compact small mb-10" data-v-bd5a78e6> 하이웍스 공용 UI 라이브러리 문서 <i class="icon right xi-link" data-v-bd5a78e6></i><a class="link" href="https://noistommy.github.io/hw_ui/#/" target="_blank" data-v-bd5a78e6></a></div><h5 id="폰트-다운로드-사이트-구현" tabindex="-1" data-v-bd5a78e6>폰트 다운로드 사이트 구현 <a class="header-anchor" href="#폰트-다운로드-사이트-구현" aria-label="Permalink to &quot;폰트 다운로드 사이트 구현&quot;" data-v-bd5a78e6>​</a></h5><ul data-v-bd5a78e6><li data-v-bd5a78e6><strong data-v-bd5a78e6>문제</strong>: 기존의 개발 방식이 아닌 스크롤 인터렉티브 방식의 사이트 구현 요청.</li><li data-v-bd5a78e6><strong data-v-bd5a78e6>해결</strong>: 디자인, 기획과의 적극적인 소통과 테스트 시연등을 통해 최선의 방식으로 개발을 완료함.</li><li data-v-bd5a78e6><strong data-v-bd5a78e6>결과</strong>: 팀내에서 결과와 방식에 대해 좋은 평가를 받았고 현재까지 변경 없이 동일 기능으로 서비스중임.</li></ul><div class="be-button compact small" data-v-bd5a78e6> 가비아 폰트 다운로드 사이트 <i class="icon right xi-link" data-v-bd5a78e6></i><a class="link" href="https://font.gabia.com/" target="_blank" data-v-bd5a78e6></a></div></div><h3 id="엔쓰리엔-주-frontend-developer" tabindex="-1" data-v-bd5a78e6>엔쓰리엔(주) <span class="be-gray-text light" data-v-bd5a78e6>| Frontend Developer</span> <a class="header-anchor" href="#엔쓰리엔-주-frontend-developer" aria-label="Permalink to &quot;엔쓰리엔(주) &lt;span class=&quot;be-gray-text light&quot;&gt;| Frontend Developer&lt;/span&gt;&quot;" data-v-bd5a78e6>​</a></h3><p class="range-date" data-v-bd5a78e6>2017.10 – 2019.11 (2Y 1M)</p><blockquote data-v-bd5a78e6><p data-v-bd5a78e6><strong data-v-bd5a78e6>관제 솔루션 내부 데이터를 활용한 SI 개발</strong></p></blockquote><div class="py-10" data-v-bd5a78e6><h5 id="관제-솔루션-내부-데이터-시각화" tabindex="-1" data-v-bd5a78e6>관제 솔루션 내부 데이터 시각화 <a class="header-anchor" href="#관제-솔루션-내부-데이터-시각화" aria-label="Permalink to &quot;관제 솔루션 내부 데이터 시각화&quot;" data-v-bd5a78e6>​</a></h5><p data-v-bd5a78e6>주 프로젝트와 별개의 신규 SI 개발을 전담하여 고객사별 다양한 데이터를 상황에 맞도록 직접 기획, UI 설계를 주도적으로 함. 다양한 요구사항에 맞도록 재사용 가능한 차트 컴포넌트를 개발하여 개발 및 유지보수 생산성을 향상.</p><h5 id="재난-대응-관리-솔루션" tabindex="-1" data-v-bd5a78e6>재난 대응 관리 솔루션 <a class="header-anchor" href="#재난-대응-관리-솔루션" aria-label="Permalink to &quot;재난 대응 관리 솔루션&quot;" data-v-bd5a78e6>​</a></h5><p data-v-bd5a78e6>솔루션의 내부 기능으로 개발 이후 독립된 솔루션으로 확장 되도록 기여함. 기획, 개발, UI/UX 설계 전 과정 참여하여 직접 고객사와 소통하는 과정을 통해 UI/UX 설계 경험 향상</p></div><h3 id="snmp-소셜-네트워크-마케팅-플랫폼-frontend-developer" tabindex="-1" data-v-bd5a78e6>SNMP(소셜 네트워크 마케팅 플랫폼) <span class="be-gray-text light" data-v-bd5a78e6>| Frontend Developer</span> <a class="header-anchor" href="#snmp-소셜-네트워크-마케팅-플랫폼-frontend-developer" aria-label="Permalink to &quot;SNMP(소셜 네트워크 마케팅 플랫폼) &lt;span class=&quot;be-gray-text light&quot;&gt;| Frontend Developer&lt;/span&gt;&quot;" data-v-bd5a78e6>​</a></h3><p class="range-date" data-v-bd5a78e6>2014.08 – 2016.10 (2Y 2M)</p><div class="py-10" data-v-bd5a78e6><h5 id="모바일-기반-오픈마켓-플랫폼" tabindex="-1" data-v-bd5a78e6>모바일 기반 오픈마켓 플랫폼 <a class="header-anchor" href="#모바일-기반-오픈마켓-플랫폼" aria-label="Permalink to &quot;모바일 기반 오픈마켓 플랫폼&quot;" data-v-bd5a78e6>​</a></h5><ul data-v-bd5a78e6><li data-v-bd5a78e6>오픈마켓 웹 및 관리자 플랫폼, 브랜드 페이지 개발</li><li data-v-bd5a78e6>마케팅 페이지 개발</li></ul></div><h2 id="프로젝트-링크" tabindex="-1" data-v-bd5a78e6>프로젝트 &amp; 링크 <a class="header-anchor" href="#프로젝트-링크" aria-label="Permalink to &quot;프로젝트 &amp; 링크&quot;" data-v-bd5a78e6>​</a></h2><div class="py-10" data-v-bd5a78e6><h5 id="frog-ui-디자인-시스템" tabindex="-1" data-v-bd5a78e6>Frog UI 디자인 시스템 <a class="header-anchor" href="#frog-ui-디자인-시스템" aria-label="Permalink to &quot;Frog UI 디자인 시스템&quot;" data-v-bd5a78e6>​</a></h5><div class="be flex between" data-v-bd5a78e6><div class="gray-txt-40" data-v-bd5a78e6>2021 - 현재</div><div class="be-tags attached" data-v-bd5a78e6><a href="https://frog-ui-css.vercel.app" target="_blank" class="be-tag label" data-v-bd5a78e6>Frog UI</a></div></div><ul data-v-bd5a78e6><li data-v-bd5a78e6>디자인 토큰을 활용한 scss기반 시멘틱 디자인 시스템</li><li data-v-bd5a78e6>22개 컴포넌트 스타일, 다크모드 지원</li><li data-v-bd5a78e6>빌드를 통해 정적 파일 생성</li><li data-v-bd5a78e6><a href="https://github.com/noistommy/frog-ui-css.git" target="_blank" rel="noreferrer" data-v-bd5a78e6>github</a></li></ul><h5 id="ui-컴포넌트-라이브러리" tabindex="-1" data-v-bd5a78e6>UI 컴포넌트 라이브러리 <a class="header-anchor" href="#ui-컴포넌트-라이브러리" aria-label="Permalink to &quot;UI 컴포넌트 라이브러리&quot;" data-v-bd5a78e6>​</a></h5><div class="be flex between" data-v-bd5a78e6><div class="gray-txt-40" data-v-bd5a78e6>2021 - 현재</div><div class="be-tags" data-v-bd5a78e6><a href="https://beui.vercel.app" target="_blank" class="be-tag label" data-v-bd5a78e6>BEUI vue </a><a href="https://react-be-ui.vercel.app" target="_blank" class="be-tag label" data-v-bd5a78e6>BEUI react </a></div></div><ul data-v-bd5a78e6><li data-v-bd5a78e6>npm 설치 가능한 Headless UI 라이브러리</li><li data-v-bd5a78e6>React, Vue 개별 라이브러리</li><li data-v-bd5a78e6>약 24개 컴포넌트 제공</li><li data-v-bd5a78e6>npm 누적 다운로드(최근 1년): vue용(2128회), react용(2025회)</li><li data-v-bd5a78e6><a href="https://github.com/noistommy/beui.git" target="_blank" rel="noreferrer" data-v-bd5a78e6>github(vue)</a>, <a href="https://github.com/noistommy/react-be-ui.git" target="_blank" rel="noreferrer" data-v-bd5a78e6>github(react)</a></li></ul><h5 id="모듈-vue" tabindex="-1" data-v-bd5a78e6>모듈 (vue) <a class="header-anchor" href="#모듈-vue" aria-label="Permalink to &quot;모듈 (vue)&quot;" data-v-bd5a78e6>​</a></h5><div class="be flex between" data-v-bd5a78e6><div class="gray-txt-40" data-v-bd5a78e6>2021 - 2025</div><div class="be-tags" data-v-bd5a78e6><a href="https://noistommy.github.io/vue-nt-modal" target="_blank" class="be-tag label" data-v-bd5a78e6>vue-nt-modal </a><a href="https://noistommy.github.io/vue-nt-modal" target="_blank" class="be-tag label" data-v-bd5a78e6>vue-nt-modal </a></div></div><ul data-v-bd5a78e6><li data-v-bd5a78e6>npm 설치 가능한 공용 모듈</li><li data-v-bd5a78e6><em data-v-bd5a78e6>Eventbus</em>, <em data-v-bd5a78e6>Teleport</em>를 활용한 modal, toast, tooltip 모듈</li><li data-v-bd5a78e6>npm 누적 다운로드(최근 1년): modal(903회), toast(917회), tooltip(1067회)</li><li data-v-bd5a78e6><a href="https://github.com/noistommy/vue-nt-modal.git" target="_blank" rel="noreferrer" data-v-bd5a78e6>github(modal)</a>, <a href="https://github.com/noistommy/vue-nt-toast.git" target="_blank" rel="noreferrer" data-v-bd5a78e6>github(toast)</a>, <a href="https://github.com/noistommy/vue-nt-tooltip.git" target="_blank" rel="noreferrer" data-v-bd5a78e6>github(tooltip)</a></li></ul><h5 id="모듈-react" tabindex="-1" data-v-bd5a78e6>모듈 (react) <a class="header-anchor" href="#모듈-react" aria-label="Permalink to &quot;모듈 (react)&quot;" data-v-bd5a78e6>​</a></h5><div class="be flex between" data-v-bd5a78e6><div class="gray-txt-40" data-v-bd5a78e6>2026</div><div class="be-tags shrink-0" data-v-bd5a78e6><a href="https://noistommy.github.io/react-nt-modal" target="_blank" class="be-tag label" data-v-bd5a78e6>react-nt-modal </a><a href="https://noistommy.github.io/react-nt-modal" target="_blank" class="be-tag label" data-v-bd5a78e6>react-nt-toast </a></div></div><ul data-v-bd5a78e6><li data-v-bd5a78e6>npm 설치 가능한 공용 모듈</li><li data-v-bd5a78e6><em data-v-bd5a78e6>Provider</em>, <em data-v-bd5a78e6>Potal</em>를 활용한 modal, toast 모듈</li><li data-v-bd5a78e6>npm 누적 다운로드(최근 1년): modal(1671회), toast(534회)</li><li data-v-bd5a78e6><a href="https://github.com/noistommy/react-nt-modal.git" target="_blank" rel="noreferrer" data-v-bd5a78e6>github(modal)</a>, <a href="https://github.com/noistommy/react-nt-toast.git" target="_blank" rel="noreferrer" data-v-bd5a78e6>github(toast)</a></li></ul></div><h2 id="tech-stack" tabindex="-1" data-v-bd5a78e6>Tech Stack <a class="header-anchor" href="#tech-stack" aria-label="Permalink to &quot;Tech Stack&quot;" data-v-bd5a78e6>​</a></h2><ul data-v-bd5a78e6><li data-v-bd5a78e6>Language: TypeScript, JavaScript(ES6+)</li><li data-v-bd5a78e6>Framework: Vue 2/3, Nuxt.js, React, Next.js</li><li data-v-bd5a78e6>Build &amp; Tooling: Vite, Webpack, Gulp</li><li data-v-bd5a78e6>UI &amp; Design System: 자체 UI 라이브러리(FROG UI, BEUI, HWUI) 제작, Headless UI 패턴 설계</li><li data-v-bd5a78e6>Visualization &amp; Graphics: SVG, Canvas, Charting 라이브러리, 인터랙션, 애니메이션(Transition)</li><li data-v-bd5a78e6>Infra &amp; 기타: Git(github, gitlab), jira, slack 등</li></ul><h2 id="학력" tabindex="-1" data-v-bd5a78e6>학력 <a class="header-anchor" href="#학력" aria-label="Permalink to &quot;학력&quot;" data-v-bd5a78e6>​</a></h2><ul data-v-bd5a78e6><li data-v-bd5a78e6><strong data-v-bd5a78e6>국립공주대학교</strong> — 컴퓨터·멀티미디어공학 전공 (2008.02 졸업)</li></ul>',22)])])}const p=l(s,[["render",b],["__scopeId","data-v-bd5a78e6"]]);export{m as __pageData,p as default};
